#!/usr/bin/env python3
"""
Message Delete Tool — Remove tool call results from the current conversation context.

Supports two deletion modes:
1. By indices:  delete_messages(indices=[0, 1])  — delete by position
2. By patterns: delete_messages(patterns=["memory", "web_search"])  — match tool names

The tool returns a special marker that causes the agent to remove matched messages
from the conversation history before the next API call.
"""

from __future__ import annotations

import json
import logging
from typing import Any, Dict, List, Optional

logger = logging.getLogger(__name__)

# Special prefix that signals the executor to delete messages
_DELETE_MARKER_PREFIX = "__DELETE_MESSAGES__:"

# Schema for the delete_messages tool
DELETE_MESSAGES_SCHEMA = {
    "name": "delete_messages",
    "description": (
        "Delete tool call results from the current conversation context. "
        "Supports deletion by index (position in last tool batch) or by "
        "tool name pattern. Deleted messages are permanently removed from "
        "context and won't appear in subsequent API calls. Use when you need "
        "to undo or hide sensitive/wrong tool results. Note: only works on "
        "tool results from the immediately preceding tool call batch."
    ),
    "parameters": {
        "type": "object",
        "properties": {
            "indices": {
                "type": "array",
                "items": {"type": "integer"},
                "description": (
                    "List of 0-based indices to delete from the last tool call batch. "
                    "Example: [0, 2] deletes 1st and 3rd results. "
                    "Only valid for the immediately preceding batch."
                ),
            },
            "patterns": {
                "type": "array",
                "items": {"type": "string"},
                "description": (
                    "List of tool name patterns to delete. Matches partial names "
                    "(case-insensitive). Example: ['memory', 'web'] matches "
                    "'memory_palace', 'memory_search', and 'web_search'."
                ),
            },
            "count": {
                "type": "integer",
                "description": (
                    "Delete last N tool results (regardless of tool name). "
                    "Use to quickly remove trailing results without counting indices. "
                    "Cannot be used with patterns or indices."
                ),
            },
        },
        "additionalProperties": False,
    },
}


def _check_delete_marker(result: str) -> Optional[Dict[str, Any]]:
    """Parse delete指令 from a tool result string if present."""
    if not result or not isinstance(result, str):
        return None
    if result.startswith(_DELETE_MARKER_PREFIX):
        try:
            return json.loads(result[len(_DELETE_MARKER_PREFIX):])
        except json.JSONDecodeError:
            logger.warning(f"Failed to parse delete marker: {result[:200]}")
    return None


def delete_messages(
    indices: Optional[List[int]] = None,
    patterns: Optional[List[str]] = None,
    count: Optional[int] = None,
) -> str:
    """
    Delete tool call results from the current conversation context.

    Args:
        indices: List of 0-based indices to delete from last tool batch.
                 Example: [0, 1] deletes first two tool results.
        patterns: List of tool name patterns (case-insensitive, partial match).
                  Example: ['memory', 'web'] matches 'memory_palace', 'web_search'.
        count: Delete last N tool results. Cannot be used with indices or patterns.

    Returns:
        A special marker string that the executor will parse to delete messages.
        The actual deletion happens in the tool executor, not here.

    Examples:
        delete_messages(indices=[0])                    # delete first result
        delete_messages(indices=[0, 1])                 # delete first two
        delete_messages(patterns=['memory'])            # delete memory tool results
        delete_messages(patterns=['memory', 'web'])      # delete matching patterns
        delete_messages(count=3)                         # delete last 3 results
    """
    # Validate arguments
    if indices is not None and patterns is not None:
        return json.dumps({
            "error": "Cannot specify both 'indices' and 'patterns'. Choose one."
        })
    if count is not None and (indices is not None or patterns is not None):
        return json.dumps({
            "error": "Cannot use 'count' with 'indices' or 'patterns'. Choose one."
        })
    if count is not None and count < 1:
        return json.dumps({
            "error": "'count' must be a positive integer."
        })
    if indices is not None and not all(i >= 0 for i in indices):
        return json.dumps({
            "error": "All indices must be non-negative integers."
        })

    # Build the delete instruction
    instruction: Dict[str, Any] = {"action": "delete_tool_results"}

    if indices is not None:
        instruction["indices"] = sorted(set(indices))  # deduplicate
    elif patterns is not None:
        instruction["patterns"] = [p.lower() for p in patterns]
    elif count is not None:
        instruction["count"] = count
    else:
        return json.dumps({
            "error": "Must specify at least one of: indices, patterns, count."
        })

    # Return the special marker that the executor will parse
    return _DELETE_MARKER_PREFIX + json.dumps(instruction)


def apply_delete_instruction(
    messages: List[Dict[str, Any]],
    instruction: Dict[str, Any],
    last_tool_batch_start: int,
    last_tool_batch_count: int,
) -> List[Dict[str, Any]]:
    """
    Apply a delete instruction to the messages list.

    Args:
        messages: The full conversation messages list.
        instruction: The parsed delete instruction from delete_messages tool.
        last_tool_batch_start: Index in messages where last tool batch starts.
        last_tool_batch_count: Number of tool results in the last batch.

    Returns:
        Modified messages list with specified tool results removed.
    """
    if instruction.get("action") != "delete_tool_results":
        return messages

    # Build list of indices to delete (relative to last batch)
    to_delete: List[int] = []

    if "indices" in instruction:
        # Validate indices are in range
        for idx in instruction["indices"]:
            if idx < last_tool_batch_count:
                to_delete.append(idx)
            else:
                logger.warning(f"Index {idx} out of range for batch of {last_tool_batch_count}")

    elif "patterns" in instruction:
        # Match tool names by pattern
        patterns = instruction["patterns"]
        for i in range(last_tool_batch_count):
            msg_idx = last_tool_batch_start + i
            if msg_idx >= len(messages):
                break
            msg = messages[msg_idx]
            tool_name = msg.get("name", "").lower()
            content = str(msg.get("content", "")).lower()

            for pattern in patterns:
                if pattern in tool_name or pattern in content:
                    to_delete.append(i)
                    break

    elif "count" in instruction:
        # Delete last N results
        count = instruction["count"]
        to_delete = list(range(max(0, last_tool_batch_count - count), last_tool_batch_count))

    if not to_delete:
        return messages

    # Remove messages in reverse order to maintain correct indices
    to_delete = sorted(set(to_delete), reverse=True)
    for idx in to_delete:
        msg_idx = last_tool_batch_start + idx
        if msg_idx < len(messages):
            deleted = messages.pop(msg_idx)
            logger.debug(f"Deleted message at index {msg_idx}: {deleted.get('name', 'unknown')}")

    return messages


# Register the tool
def register():
    """Register this tool with the registry."""
    from tools.registry import registry

    def handler(args: dict) -> str:
        return delete_messages(
            indices=args.get("indices"),
            patterns=args.get("patterns"),
            count=args.get("count"),
        )

    registry.register(
        name="delete_messages",
        toolset="core",
        schema=DELETE_MESSAGES_SCHEMA,
        handler=handler,
        description="Delete tool call results from conversation context",
        emoji="🗑️",
    )


# Auto-register on import
register()

