    return None


def forget(
    *args,
    indices: Optional[List[int]] = None,
    patterns: Optional[List[str]] = None,
    count: Optional[int] = None,
) -> str:
    """
    Delete tool call results from the current conversation context.

    Supports flexible calling conventions:
    - forget(0, 1)                     — by indices (positional)
    - forget("memory")                 — by pattern (positional)
    - forget(indices=[0, 1])           — by indices (keyword)
    - forget(patterns=["memory"])      — by patterns (keyword)
    - forget(-3)                       — delete last 3

    Args:
        *args: Positional arguments - can be integers (indices) or strings (patterns).
        indices: List of 0-based indices to delete from last tool batch.
        patterns: List of tool name patterns (case-insensitive, partial match).
        count: Delete last N tool results (negative means from end).

    Returns:
        A special marker string that the executor will parse to delete messages.

    Examples:
        forget(0)                    # delete first result
        forget(0, 1)                 # delete first two results
        forget("memory")             # delete memory-related results
        forget("memory palace")      # delete memory palace results
        forget(-3)                   # delete last 3 results
        forget(indices=[0, 2])       # delete by indices (explicit)
        forget(patterns=["web"])     # delete by pattern (explicit)
    """
    # Parse positional arguments
    positional_indices: List[int] = []
    positional_patterns: List[str] = []
    seen_count: Optional[int] = None

    for arg in args:
        if isinstance(arg, int):
            # Negative integers are treated as count (from end)
