        return json.dumps({
            "error": "All indices must be non-negative integers."
        })

    # Build the delete instruction
    instruction: Dict[str, Any] = {"action": "delete_tool_results"}

    if final_indices:
        instruction["indices"] = sorted(set(final_indices))  # deduplicate
    elif final_patterns:
        instruction["patterns"] = [p.lower() for p in final_patterns]
    elif final_count is not None:
        instruction["count"] = final_count
    else:
        return json.dumps({
            "error": "Must specify at least one of: indices (or positional int), patterns (or positional str), count (or negative int)."
        })

    # Return the special marker that the executor will parse
    return _DELETE_MARKER_PREFIX + json.dumps(instruction)


